def gini(labels):
    n = len(labels)
    if n == 0:
        return 0.0
    counts = {}
    for lb in labels:
        counts[lb] = counts.get(lb, 0) + 1
    return 1.0 - sum((c / n) ** 2 for c in counts.values())

data = [(1.0, 'A'), (2.0, 'A'), (3.0, 'B'), (4.0, 'B'), (5.0, 'B')]

best_thr, best_gain = None, -1
root_g = gini([lb for _, lb in data])
for thr in [1.5, 2.5, 3.5, 4.5]:
    left  = [lb for x, lb in data if x <= thr]
    right = [lb for x, lb in data if x >  thr]
    gain = root_g - (len(left)/len(data))*gini(left) - (len(right)/len(data))*gini(right)
    if gain > best_gain:
        best_gain, best_thr = gain, thr

print(f"Best split: x <= {best_thr}")
print(f"Gain: {best_gain:.4f}")
